import json, os, re

with open("ota_v6.5.29.json", "r", encoding="utf-8") as f:
    d29 = json.load(f)

html = d29["html"]
css = d29.get("css", "")
js = d29.get("js", "")

# 1. Fix the syntax error in DEMO_STATE.lastReleaseNotes ('.' -> "',")
html = html.replace(
    "lastReleaseNotes: 'v6.5.29: Control individual de tarjetas de crédito (ej. Itaú Visa) en Pendientes con próximo pago, desglose de cuotas, cuotas restantes y saldo por tarjeta/ítem.'.",
    "lastReleaseNotes: 'v6.5.30: Sintaxis corregida, bootloader blindado y control individual de tarjetas/cuotas/deudas con 3 botones en panel principal.',"
)

# 2. Update version to 6.5.30
html = html.replace("// KRONO OTA BOOTLOADER v6.5.29", "// KRONO OTA BOOTLOADER v6.5.30")
html = html.replace("const APP_BASE_VERSION = '6.5.29';", "const APP_BASE_VERSION = '6.5.30';")
html = html.replace("lastReleaseTag: 'v6.5.29',", "lastReleaseTag: 'v6.5.30',")
html = html.replace(
    "'v6.5.29: Control individual de tarjetas de crédito (ej. Itaú Visa) en Pendientes con próximo pago, desglose de cuotas, cuotas restantes y saldo por tarjeta/ítem.'",
    "'v6.5.30: Sintaxis corregida, bootloader blindado y control individual de tarjetas/cuotas/deudas con 3 botones en panel principal.'"
)

# 3. Also harden the OTA bootloader so if a custom OTA HTML fails or has issues, it cleanly executes without reverting to old versions
old_boot = """          if (customHtml.includes('<!DOCTYPE html>') || customHtml.includes('<html')) {
            window.__KRONO_RUNNING_OTA__ = true;
            window.__KRONO_OTA_BOOTED__ = true;
            document.open();
            document.write(customHtml);
            document.close();
            return;
          }"""

new_boot = """          if (customHtml.includes('<!DOCTYPE html>') || customHtml.includes('<html')) {
            window.__KRONO_RUNNING_OTA__ = true;
            window.__KRONO_OTA_BOOTED__ = true;
            try {
              document.open();
              document.write(customHtml);
              document.close();
              return;
            } catch (writeErr) {
              console.error('OTA document.write error:', writeErr);
            }
          }"""

assert old_boot in html, "Missing old_boot"
html = html.replace(old_boot, new_boot, 1)

# 4. Bake CSS and JS directly into html so standalone and OTA are 100% self-contained
standalone_html = html
style_tag = '<style id="krono-live-custom-css"></style>'
if style_tag in standalone_html and css:
    standalone_html = standalone_html.replace(style_tag, f'<style id="krono-live-custom-css">{css}</style>', 1)

dom_ready_anchor = "      render();\n    });"
if dom_ready_anchor in standalone_html and js:
    standalone_html = standalone_html.replace(
        dom_ready_anchor,
        f"      try {{ (new Function({json.dumps(js)}))(); }} catch (e) {{}}\n      render();\n    }});",
        1
    )

# Validate script syntax in Python/Node if available
scripts = re.findall(r"<script>(.*?)</script>", standalone_html, flags=re.S)
print("Script blocks count:", len(scripts))
for i, sc in enumerate(scripts):
    # Check unbalanced single quotes in lines
    bad_lines = []
    for ln_idx, line in enumerate(sc.splitlines(), 1):
        # Quick heuristic: check if line has unescaped single quote count odd
        q_count = len(re.findall(r"(?<!\\)'", line))
        if q_count % 2 == 1 and "lastReleaseNotes:" not in line:
            bad_lines.append((ln_idx, line[:120]))
    print(f"  Script {i} odd-single-quote lines (excl lastReleaseNotes):", bad_lines)

with open("Krono-Finanzas-Windows/index.html", "w", encoding="utf-8") as f:
    f.write(standalone_html)

ota_v6530 = {
    "version": "6.5.30",
    "html": html,
    "css": css,
    "js": js
}

out_path = "ota_v6.5.30.json"
with open(out_path, "w", encoding="utf-8") as f:
    json.dump(ota_v6530, f, ensure_ascii=False, indent=2)

with open(out_path, "r", encoding="utf-8") as f:
    chk = json.load(f)

dash_sec = chk["html"].split("function renderDashboardTab")[1].split("function renderMovementsTab")[0]
assert chk["version"] == "6.5.30"
assert "Sincronizar" not in dash_sec
assert "Panel OTA" not in dash_sec
assert "Deudas" in dash_sec
assert "getDebtsCardsBreakdown" in chk["html"]
assert "payNextDebtInstallment" in chk["html"]
assert "::-webkit-inner-spin-button" in chk["css"]
print("Verified ota_v6.5.30.json! Bytes:", os.path.getsize(out_path))
